/**
 * 自建题目：用户自己在练习册里出的题，按题卷分组存在本地。
 * 和知识卡片（knowledgeNotes）一样只放 localStorage，不依赖后端。
 */
export interface CustomPracticeQuestion {
  id: string;
  trackId: string;
  prompt: string;
  answer: string;
  explanationZh: string;
  createdAt: number;
}

const STORAGE_KEY = "leafia.practice.customQuestions.v1";

function sanitize(value: unknown): CustomPracticeQuestion | null {
  if (!value || typeof value !== "object") return null;
  const record = value as Record<string, unknown>;
  const id = typeof record.id === "string" ? record.id : "";
  const trackId = typeof record.trackId === "string" ? record.trackId : "";
  const prompt = typeof record.prompt === "string" ? record.prompt.trim() : "";
  const answer = typeof record.answer === "string" ? record.answer.trim() : "";
  if (!id || !trackId || !prompt || !answer) return null;
  return {
    id,
    trackId,
    prompt,
    answer,
    explanationZh:
      typeof record.explanationZh === "string" ? record.explanationZh.trim() : "",
    createdAt:
      typeof record.createdAt === "number" && Number.isFinite(record.createdAt)
        ? record.createdAt
        : Date.now(),
  };
}

export function loadCustomQuestions(): CustomPracticeQuestion[] {
  if (typeof window === "undefined") return [];
  try {
    const raw = window.localStorage.getItem(STORAGE_KEY);
    if (!raw) return [];
    const parsed: unknown = JSON.parse(raw);
    if (!Array.isArray(parsed)) return [];
    return parsed
      .map(sanitize)
      .filter((item): item is CustomPracticeQuestion => item !== null);
  } catch {
    return [];
  }
}

export function saveCustomQuestions(items: CustomPracticeQuestion[]) {
  if (typeof window === "undefined") return;
  try {
    window.localStorage.setItem(STORAGE_KEY, JSON.stringify(items));
  } catch {
    // 存储失败（隐私模式等）时静默跳过，不影响当前会话使用。
  }
}

export function createCustomQuestion(input: {
  trackId: string;
  prompt: string;
  answer: string;
  explanationZh: string;
}): CustomPracticeQuestion {
  return {
    id: `custom-${Date.now().toString(36)}-${Math.random().toString(36).slice(2, 7)}`,
    trackId: input.trackId,
    prompt: input.prompt.trim(),
    answer: input.answer.trim(),
    explanationZh: input.explanationZh.trim(),
    createdAt: Date.now(),
  };
}
